            <script>
            // Handle keyboard events for closing the categories dropdown
            // Close dropdown when ESC key is pressed
            window.onkeydown = function( event ) {
                if ( event.keyCode == 27 ) {
                    document.getElementById("categoriesList").classList.remove("show");
                }
            };
            
            // Close dropdown when clicking outside
            // Checks if click target is outside both the dropdown and trigger button
            document.addEventListener('click', function(event) {
                var dropdown = document.getElementById("categoriesList");
                var button = document.getElementById("categoriesListBtn");
                if (!dropdown.contains(event.target) && !button.contains(event.target)) {
                    dropdown.classList.remove("show");
                }
            });
            
            // Function to filter courses in the categories dropdown based on search input
            function filterFunction() {
              // Declare variables for DOM elements and filter value
              var input, filter, ul, li, a, i;
              input = document.getElementById("searchCourses");
              filter = input.value.toUpperCase();
              div = document.getElementById("categoriesList");
              a = div.getElementsByTagName("a");
              // Loop through all list items and hide those that don't match the search query
              for (i = 0; i < a.length; i++) {
                txtValue = a[i].textContent || a[i].innerText;
                if (txtValue.toUpperCase().indexOf(filter) > -1) {
                  a[i].style.display = ""; // Show matching items
                } else {
                  a[i].style.display = "none"; // Hide non-matching items
                }
              }
            }
            </script>
            
            
