require(['jquery'], function($) {

        // Initialize hide flag to control category list visibility
        hide = true;

        // Handle clicks on the page wrapper
        $('#page-wrapper').on("click", function () {
            // Hide category list if hide flag is true
            if (hide) $('.rui-cat-list').removeClass('show');
            hide = true;
        });

        // Handle clicks on the categories list button
        $('body').on('click', '#categoriesListBtn', function () {
            var self = $(".rui-cat-list");
            // If category list is already shown, hide it
            if (self.hasClass('show')) {
                $('.rui-cat-list').removeClass('show');
                return false;
            }
            // Hide any existing shown category lists
            $('.rui-cat-list').removeClass('show');
            // Toggle show class on clicked category list
            self.toggleClass('show');
            // Set hide flag to false to prevent immediate hiding
            hide = false;
        });

    // Handle clicks on dropdown toggle buttons within dropdown menus
    // This enables nested dropdowns/submenus to work properly
    $('.dropdown-menu a.dropdown-toggle').on('click', function(e) {

        // If the next element doesn't have show class, remove show class from any other shown dropdowns
        if (!$(this).next().hasClass('show')) {
            $(this).parents('.dropdown-menu').first().find('.show').removeClass('show');
        }

        // Toggle show class on the submenu
        var $subMenu = $(this).next('.dropdown-menu');
        $subMenu.toggleClass('show');

        // When parent dropdown is closed, close all submenus
        $(this).parents('li.nav-item.dropdown.show').on('hidden.bs.dropdown', function(e) {
            $('.dropdown-submenu .show').removeClass('show');
        });

        return false;
    
    });

});
